{
  "items": [
    {
      "name": "Finsupp.sum_of_support_subset",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] (f : α →₀ M) {s : Finset α},\n  f.support ⊆ s → ∀ (g : α → M → N), (∀ i ∈ s, g i 0 = 0) → f.sum g = ∑ x ∈ s, g x (f x)"
    },
    {
      "name": "DFinsupp.sumZeroHom",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "definition",
      "type": "{ι : Type u} →\n  {γ : Type w} →\n    {β : ι → Type v} →\n      [DecidableEq ι] →\n        [inst : (i : ι) → Zero (β i)] →\n          [inst_1 : AddCommMonoid γ] → ((i : ι) → ZeroHom (β i) γ) → ZeroHom (Π₀ (i : ι), β i) γ"
    },
    {
      "name": "tsum_eq_sum",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : AddCommMonoid α] [inst_1 : TopologicalSpace α] {f : β → α}\n  {L : SummationFilter β} [L.LeAtTop] {s : Finset β}, (∀ b ∉ s, f b = 0) → ∑'[L] (b : β), f b = ∑ b ∈ s, f b"
    },
    {
      "name": "Finsupp.sum",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "definition",
      "type": "{α : Type u_1} → {M : Type u_8} → {N : Type u_10} → [inst : Zero M] → [AddCommMonoid N] → (α →₀ M) → (α → M → N) → N"
    },
    {
      "name": "finsum",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "definition",
      "type": "{M : Type u_7} → {α : Sort u_8} → [AddCommMonoid M] → (α → M) → M"
    },
    {
      "name": "Finsupp.onFinset",
      "module_name": "Mathlib.Data.Finsupp.Defs",
      "kind": "definition",
      "type": "{α : Type u_1} → {M : Type u_4} → [inst : Zero M] → (s : Finset α) → (f : α → M) → (∀ (a : α), f a ≠ 0 → a ∈ s) → α →₀ M"
    },
    {
      "name": "finsum_def'",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {M : Type u_7} {α : Sort u_8} [inst : AddCommMonoid M] (f : α → M),\n  finsum f = if h : (Function.support (f ∘ PLift.down)).Finite then ∑ i ∈ h.toFinset, f i.down else 0"
    },
    {
      "name": "Finsupp.mapRange",
      "module_name": "Mathlib.Data.Finsupp.Defs",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  {M : Type u_4} → {N : Type u_5} → [inst : Zero M] → [inst_1 : Zero N] → (f : M → N) → f 0 = 0 → (α →₀ M) → α →₀ N"
    }
  ]
}
